\label{thm:main_thm}
    For every positive integer $n$, there exists a function $\Phi:\operatorname{\mathfrak{C}}_{B,n+1}\to B_n$ with the following properties:
    \begin{enumerate}[label=(\alph*)]
        \item for all $\pi\in \operatorname{\mathfrak{C}}_{B,n+1}$, we have $\operatorname{Des}(\pi)\cap \{0,1,\ldots,n-1\}=\operatorname{Des}(\Phi(\pi))$, and
        \item the restriction of $\Phi$ to $\operatorname{\mathfrak{C}}_{D,n+1}$ or $\overline{\operatorname{\mathfrak{C}}_{D,n+1}}$ is a bijection.
    \end{enumerate}

\label{ex:1}
    Consider the signed permutation $\sigma$ on $[\pm 6]$ defined by $\sigma(1)=-3$, $\sigma(2)=1$, $\sigma(3)=2$, $\sigma(4)=-5$, $\sigma(5)=-4$, and $\sigma(6)=6$. 
    Its one-line notation is $\sigma=[-3,1,2,-5,-4,6].$ From the property $\sigma(-i)=-\sigma(i)$ for $i\in [n]$, we find that $\sigma(-1)=3$, $\sigma(-2)=-1$, $\sigma(-3)=-2$, $\sigma(-4)=5$, $\sigma(-5)=4$, and $\sigma(-6)=-6$.

\label{ex:2}
    Let $\pi=[1,-3,-2,5,6,4]\in B_6$. Letting $\sigma\in B_6$ be the permutation from \cref{ex:1}, we have that
    $\pi \sigma = [2,1,-3,-6,-5,4].$ Observe that $\pi\in D_6$, while $\sigma,\pi\sigma\notin D_6$.

\label{ex:3}
    The permutation $\sigma$ from \cref{ex:1} can be expressed as \[\begin{pmatrix} 1 & 3 & 2 \\ -3 & 2 & 1 \end{pmatrix} \begin{pmatrix}
    4 & 5 \\ -5 & -4 
\end{pmatrix} \begin{pmatrix}
    6 \\ -6
\end{pmatrix}=(-3, 2, 1)(-5, -4)(6).\]
Observe that the set of elements that appear in the cycle notation and one-line notation coincide, and we will use this fact freely throughout our work.

Let $(X_n)_{n\geq 1}$ be a sequence of real-valued random variables, and let $X$ be a real-valued random variable. Define $F_n(x)=P(X_n\leq x)$ and $F(x)=P(X\leq x)$ to be their respective cumulative distribution functions. 
    \begin{enumerate}[label=(\alph*)]
        \item $X_n$ \emph{converges in distribution} to $X$, denoted $X_n\xrightarrow{d} X$, if $F_n(x)\to F(x)$ for all $x$ that are continuity points of $F$. 
        \item $X_n$ \emph{converges in probability} to $X$, denoted $X_n\xrightarrow{p} X$, if for all $\epsilon>0$, we have that 
        \begin{equation}\label{eq:converge}
            \lim_{n\to\infty} P(|X_n-X|>\epsilon)= 0.
        \end{equation}
    \end{enumerate}
    It is well known that convergence in probability implies convergence in distribution.

\label{thm:CLLSY}
    Let $X_n$ be the random variable corresponding to the descent statistic on $\operatorname{\mathfrak{C}}_{B,n},\operatorname{\mathfrak{C}}_{D,n}$, or $\overline{\operatorname{\mathfrak{C}}_{D,n}}$, and let $Y_n$ be the corresponding random variable on 
    $B_n$. If $n\geq 5$, then the mean and variance of $X_n$ are the same as the mean and variance of $Y_n$, respectively.

\label{thm:CLLSY2}
    Let $X_n$ be the random variable corresponding to the flag major index statistic on $\operatorname{\mathfrak{C}}_{B,n},\operatorname{\mathfrak{C}}_{D,n}$, or $\overline{\operatorname{\mathfrak{C}}_{D,n}}$, and let $Y_n$ be the corresponding random variable on 
    $B_n$. If $n\geq 5$, then the mean and variance of $X_n$ are the same as the mean and variance of $Y_n$, respectively.

\label{ex:phi2}
    For a larger example, consider 
    \begin{equation*}
        \begin{split}
            \pi & =(1,-4,8,-6, 11, 2, -3, 7,  -5, 10, 12,  9,13) \\
            & =[-4,-3,7,8,10,11,-5,-6,13,12,2,9,1]\in \operatorname{\mathfrak{C}}_{B,13}^+,
        \end{split}
    \end{equation*}
    which has descent set $\{0,6,7,9,10,12\}$. The algorithm begins with
    \begin{equation*}
        \begin{split}
            \sigma & =(1,-4)(8,-6)(11, 2, -3, 7,-5, 10)(12, 9) \\ & =[-4,-3,7,1,10,8,-5,-6,12,11,2,9].
        \end{split}
    \end{equation*}


    In the first iteration of the \texttt{for} loop, we see that $P_{\pi,\sigma}(4,3)$ is \texttt{True} and $P_{\pi,\sigma}(4,5)$ is \texttt{False}, so the algorithm performs swaps beginning with $4$ and $3$ to obtain
    \begin{equation*}
        \begin{split}
            \sigma & =(2,-3)(8,-6)(11, 1, -4, 7, -5, 10)(12, 9) \\ & =[-4,-3,2,7,10,8,-5,-6,12,11,1,9].
        \end{split}
    \end{equation*}
    Since $P_{\pi,\sigma}(3,2)$ is \texttt{False}, the first iteration of the \texttt{for} loop ends here. 

    In the second iteration, $P_{\pi,\sigma}(6,5)$ is \texttt{True} and $P_{\pi,\sigma}(6,7)$ is \texttt{False}, so the algorithm performs swaps beginning with $6$ and $5$ to obtain
    \begin{equation*}
        \begin{split}
            \sigma & =(2,-3)(7,-5)(11, 1, -4,8,- 6, 10)(12,9) \\ & =[-4,-3,2,8,7,10,-5,-6,12,11,1,9].
        \end{split}
    \end{equation*}
    Since $P_{\pi,\sigma}(5,4)$ is now \texttt{True}, the algorithm performs further swaps beginning with $5$ and $4$ to obtain
    \begin{equation*}
        \begin{split}
            \sigma & =(2,-3)(7,-4)(11, 1, -5,8, -6, 10)(12,9) \\ & =[-5,-3,2,7,8,10,-4,-6,12,11,1,9].
        \end{split}
    \end{equation*}
    As $P_{\pi,\sigma}(4,3)$ is \texttt{False}, the second iteration of the \texttt{for} loop end here.

    In the third iteration, both $P_{\pi,\sigma}(10,11)$ and $P_{\pi,\sigma}(10,9)$ are \texttt{False}. Hence, the algorithm does not perform any swaps, so
    \begin{equation*}
        \begin{split}
            \phi(\pi) & =(2,-3)(7,-4)(11, 1, -5,8, -6, 10)(12,9) \\ & =[-5,-3,2,7,8,10,-4,-6,12,11,1,9].
        \end{split}
    \end{equation*}
    This has descent set $\{0,6,7,9,10\}$, and this matches $\operatorname{Des}(\pi)$ at all elements except $12$, which is not a possible descent for $\phi(\pi)\in B_{12}$.

The \emph{order properties} of ${\sigma}$ are the following.  
\begin{enumerate}[label=(\Alph*)]
    \item The relative order of elements within each cycle $\sigma_1,\ldots,\sigma_m$ matches the relative order within the respective cycle of $\pi_1,\ldots,\pi_m$. In particular, the largest element in each cycle is the first one. \label{op:relative}
    \item The first elements of the cycles satisfy $\sigma_{1,1}<\sigma_{2,1}<\dots <\sigma_{m,1}$. Additionally, for every $i\in [m]$, the first element $\sigma_{i,1}$ is the largest element that appears in $\sigma_1,\sigma_2,\ldots,\sigma_i$. \label{op:first}
    \item Suppose $x\in [\pm n]$ appears in the cycle notation of $\sigma$, and let $k\geq j+1$. Then $\pi(|x|)>\pi_{k,1}$ if and only if $\sigma(|x|)\geq \sigma_{k,1}$, where equality holds when $x\in \sigma_k$ is the last element. Furthermore, any $x$ satisfying these equivalent properties has not been involved in any swaps.\label{op:large}
    \item If $d\in [n-1]$ is in symmetric difference $\operatorname{Des}_{\Delta}(\pi,\sigma)$, then exactly one of $\pm d$ and $\pm (d+1)$ is the last element in some ${\sigma}_{j},\ldots,{\sigma}_{m}$ and the remaining element appears in the non-last position of some cycle to its right. Furthermore, letting $x$ be the element that appears in a last position and $\pm (x+\epsilon)$ with $\epsilon\in \{-1,1\}$ be the other element,  it must be that $\pi(|x|)>\pi(|x+\epsilon|)$ and ${\sigma}(|x|)<{\sigma}(|x+\epsilon|)$. \label{op:descents}
\end{enumerate}

The \emph{swap properties} of ${\sigma}$ are the following statements about the swaps performed on $\sigma$ by the \texttt{while} loop in line \ref{line:whileloop2}. 
    \begin{enumerate}[label=(\Roman*)]
        \item All swaps occur between an element in the $j$-th cycle and an element in a cycle to its right. \label{sp:right}
        \item The last elements in cycles $\sigma_{j+1},\ldots,\sigma_m$ are not affected by swaps. Furthermore, if the first swap is between $z\in \sigma_j$ and $\pm (z+\epsilon)$ where $\epsilon\in \{-1,1\}$, then no element right of $\pm (z+\epsilon)$ in the cycle notation of $\sigma$ is affected by a swap. \label{sp:last}
        \item If an element $x$ in the cycle notation of $\sigma$ satisfies $\sigma(|x|)\geq \sigma_{j+1,1}$, then $x$ is not affected by swaps. \label{sp:large}
        \item Suppose the last element $z\in \sigma_j$ is swapped with $\pm (z+\epsilon)$ where $\epsilon\in \{-1,1\}$. Then the following statements hold for the cumulative effects of the swaps on $\operatorname{Des}_{\Delta}(\pi,\sigma)\cap [n-1]$. \label{sp:descents}
        \begin{itemize}
            \item The descent $\min\{|z|,|z+\epsilon|\}\in \operatorname{Des}_{\Delta}(\pi,\sigma)$ is removed from the symmetric difference.
            \item Suppose $\min\{|z|,|z-\epsilon|\}\in [n-1]$. If $\min\{|z|,|z-\epsilon|\}\in \operatorname{Des}_{\Delta}(\pi,\sigma)$, then this is removed from the symmetric difference, and if $\min\{|z|,|z-\epsilon|\}\notin \operatorname{Des}_{\Delta}(\pi,\sigma)$, then this is not introduced. 
            \item Suppose $\min\{|z+\epsilon|,|z+2\epsilon|\}\in [n-1]$. If $\min\{|z+\epsilon|,|z+2\epsilon|\}\in \operatorname{Des}_{\Delta}(\pi,\sigma)$, then this descent is removed. If $\min\{|z+\epsilon|,|z+2\epsilon|\}\notin \operatorname{Des}_{\Delta}(\pi,\sigma)$ and $\sigma(|z+2\epsilon|)>\sigma(|z+\epsilon|)$, then this descent is not introduced to the symmetric difference. 
            \item Any value in $[n-1]$ that is not $\min\{|z+\epsilon|,|z+2\epsilon|\}$ cannot be introduced into the symmetric difference. 
        \end{itemize}
\end{enumerate}

If $\sigma$ is the signed permutation at the start of Algorithm \ref{algorithm}, then this follows from \cref{cor:algstart}. Otherwise, some swaps have occurred, and we will prove the result in this case by contradiction. Assume $\sigma(|z|)<\sigma(|z-\epsilon|)<\sigma(|z+\epsilon|)$ holds. Since $\min\{|z|,|z+\epsilon|\}\in \operatorname{Des}_{\Delta}(\pi,\sigma)$ and $\min\{|z|,|z-\epsilon|\}\notin \operatorname{Des}_{\Delta}(\pi,\sigma)$, it must be that
    \begin{equation}\label{eq:epsilon_orders}
        \pi(|z-\epsilon|)>\pi(|z|)>\pi(|z+\epsilon|).
    \end{equation}
    Now let $\tilde{\sigma}=\tilde{\sigma}_1\tilde{\sigma}_2\dots \tilde{\sigma}_m$ be the signed permutation prior to the last sequence of swaps, so in a previous iteration of the \texttt{while} loop, swaps on $\tilde{\sigma}$ resulted in $\sigma$. We consider two cases based on the iteration of the \texttt{for} loop. 

    First, suppose that the \texttt{for} loop was not in iteration $j$ when swaps are performed on $\tilde{\sigma}$. Then swap property \ref{sp:last} for permutations prior to $\sigma$ implies that the last element of cycle $j$ has not been involved in any swaps, and since this is $ z$ in $\sigma$, it must have been $ z$ throughout the algorithm. In particular, \eqref{eq:epsilon_orders} becomes
    \begin{equation}\label{eq:epsilon_orders2}
        \pi(|z-\epsilon|)>\pi(|z|)=\pi_{j+1,1}>\pi(|z+\epsilon|).
    \end{equation}
    From order property \ref{op:large} for $\sigma$, we conclude $\sigma(|z-\epsilon|)>\sigma_{j+1,1}$. However,  combined with $\sigma(|z+\epsilon|)>\sigma(|z-\epsilon|)$, this implies $\sigma(|z+\epsilon|)>\sigma_{j+1,1}$. Comparing with \eqref{eq:epsilon_orders2}, we see that $\pm (z+\epsilon)$ is an element contradicting order property \ref{op:large} for $\sigma$. 


    Alternatively, suppose the \texttt{for} loop was in iteration $j$ when swaps are performed on $\tilde{\sigma}$. We begin by considering the positions of $z$, $\pm (z-\epsilon)$, and $\pm (z+\epsilon)$ in the cycles of $\tilde{\sigma}$ containing them. As $z$ is the last element of $\sigma_j$, this element must have been swapped into this position during the swaps on $\tilde{\sigma}$. By construction of the algorithm, $\pm z$ must have been swapped with $\pm (z-\epsilon)$ due to $\min\{|z|,|z-\epsilon|\}\in \operatorname{Des}_{\Delta}(\pi,\tilde{\sigma})$. In particular, order property \ref{op:descents} for $\tilde{\sigma}$ implies that $\pm (z-\epsilon)$ is the last element of $\tilde{\sigma}_j$ and $\pm z$ is a non-last of a cycle to the right of $\tilde{\sigma}_j$. Order property \ref{op:descents} for $\sigma$ with $\min\{|z|,|z+\epsilon|\}\in \operatorname{Des}_{\Delta}(\pi,\sigma)$ implies that $\pm (z+\epsilon)$ is a non-last element in $\sigma_{j+1},\ldots,\sigma_m$. Then this must have been a non-last element in $\tilde{\sigma}_j,\tilde{\sigma}_{j+1},\ldots,\tilde{\sigma}_{j+1}$ by swap properties \ref{sp:right} and \ref{sp:last} for $\tilde{\sigma}$. 

   Combined, we see that $\pm (z-\epsilon)$ is the last element in $\tilde{\sigma}_j$, and both $\pm z$ and $\pm (z+\epsilon)$ are non-last elements in the cycles of $\tilde{\sigma}$ containing them. In particular, order property \ref{op:descents} for $\tilde{\sigma}$ implies that $\min\{|z|,|z+\epsilon|\}\notin \operatorname{Des}_{\Delta}(\pi,\tilde{\sigma})$. The swaps on $\tilde{\sigma}$ must introduce the descent $\min\{|z|,|z+\epsilon|\}\in \operatorname{Des}_{\Delta}(\pi,\sigma)$, so swap property \ref{sp:descents} for $\tilde{\sigma}$ implies that $\tilde{\sigma}(|z+\epsilon|)<\tilde{\sigma}(|z|)$. As order property \ref{op:descents} for $\tilde{\sigma}$ implies $\tilde{\sigma}(|z-\epsilon|)<\tilde{\sigma}(|z|)$, we see that swapping $\pm (z-\epsilon)$ and $\pm z$ results in the element following $\pm (z-\epsilon)$ being larger than the one following $\pm (z+\epsilon)$. \cref{lem:SPOP2} implies that swaps do not affect the element following $\pm (z-\epsilon)$ in the cycle notation, while they can only change what follows $\pm (z+\epsilon)$ by $1$. Hence, we conclude $\sigma(|z+\epsilon|)<\sigma(|z-\epsilon|)$, and this contradicts $\sigma(|z|)<\sigma(|z-\epsilon|)<\sigma(|z+\epsilon|)$.

\label{lem:removeddescent2}
    Suppose the order properties hold for $\sigma$, and the swap properties hold for all signed permutations prior to $\sigma$ in the algorithm. Let $z$ be the last element in $\sigma_j$, let $\pm (z+\epsilon)$ with $\epsilon\in \{-1,1\}$ be the element that it is swapped with, and suppose $\min\{|z|,|z-\epsilon|\}\in [n-1]$. 
    \begin{enumerate}[label=(\alph*)]
        \item If $\min\{|z|,|z-\epsilon|\}\in \operatorname{Des}_{\Delta}(\pi,\sigma)$, then swaps remove this descent from the symmetric difference.
        \item If $\min\{|z|,|z-\epsilon|\}\notin \operatorname{Des}_{\Delta}(\pi,\sigma)$, then swaps do not introduce this to the symmetric difference.
    \end{enumerate}

\label{lem:removeddescent3}
    Suppose the order properties hold for $\sigma$, and the swap properties hold for all signed permutations prior to $\sigma$ in the algorithm. Let $z$ be the last element in $\sigma_j$, let $\pm (z+\epsilon)$ with $\epsilon\in \{-1,1\}$ be the element that it is swapped with, and suppose $\min\{|z+\epsilon|,|z+2\epsilon|\}\in [n-1]$. 
    \begin{enumerate}[label=(\alph*)]
        \item If $\min\{|z+\epsilon|,|z+2\epsilon|\}\in \operatorname{Des}_{\Delta}(\pi,\sigma)$, then this descent is removed. 
        \item If $\min\{|z+\epsilon|,|z+2\epsilon|\}\notin \operatorname{Des}_{\Delta}(\pi,\sigma)$ and $\sigma(|z+2\epsilon|)>\sigma(|z+\epsilon|)$, then this descent is not introduced to the symmetric difference
    \end{enumerate}

\label{lem:alg2_concatenation}
    Let $0\leq i\leq h$ and $x\in [n-1]$. If $x\in \operatorname{Des}_{\Delta}(\pi^{(j,i)},\sigma^{(j,i)})$, then one of the following must be true:
    \begin{itemize}
        \item $\pm x$ appears as the last element in some cycle of $\sigma^{(j,i)}$, $\pm (x+1)$ appears as a non-last element in some cycle to the right of $\pm x$, and $\pi^{(j,i)}(x)>\pi^{(j,i)}(x+1)=\sigma^{(j,i)}(x+1)>\sigma^{(j,i)}(x)$, or
        \item $\pm (x+1)$ appears as the last element in some cycle of $\sigma^{(j,i)}$, $\pm x$ appears as a non-last element in some cycle to the right of $\pm (x+1)$, and $\pi^{(j,i)}(x+1)>\pi^{(j,i)}(x)=\sigma^{(j,i)}(x)>\sigma^{(j,i)}(x+1)$. 
    \end{itemize}

We use proof by contradiction. Assume that $P_{\pi,\sigma^{(j,0)}}(|z|,|z+\epsilon|)$ is \texttt{False} and $P_{\pi^{(j,0)},\sigma}(|z|,|z+\epsilon|)$ is \texttt{True}. \cref{lem:descents_preserved} states that $\operatorname{Des}_{\Delta}(\pi,\sigma)\cap [n-1]=\emptyset$, so this combination can only occur if $P_{\pi^{(j,0)},\sigma^{(j,0)}}(|z|,|z+\epsilon|)$ is \texttt{True}. Consequently, we have that $\min\{|z|,|z+\epsilon|\}\in \operatorname{Des}_{\Delta}(\pi^{(j,0)},\sigma^{(j,0)})$, and \cref{lem:alg2_concatenation} implies that 
    \begin{equation}\label{eq:sigma_false}
        \sigma^{(j,0)}_{j+1,1}=\pi^{(j,0)}(|z|)>\pi^{(j,0)}(|z+\epsilon|)=\sigma^{(j,0)}(|z+\epsilon|)>\sigma^{(j,0)}(|z|)=\sigma^{(j,0)}_{j,1}.
    \end{equation}
    Swap property \ref{sp:last} on all signed permutations prior to $\sigma^{(j,0)}$ in Algorithm \ref{algorithm} implies that $\pm z$ has been the last element of cycle $j$ since the beginning of Algorithm \ref{algorithm}, so $\pi(|z|)=\sigma^{(1)}_{j+1,1}$ . However, order property \ref{op:large} for $\sigma$ with \eqref{eq:sigma_false} then implies that $\pi(|z|)=\sigma^{(1)}_{j+1,1}>\pi(|z+\epsilon|)$. This contradicts $P_{\pi,\sigma^{(j,0)}}(|z|,|z+\epsilon|)$ being \texttt{False} and $\sigma^{(j,0)}(|z+\epsilon|)>\sigma^{(j,0)}(|z|)$ from \eqref{eq:sigma_false}.

Order property \ref{op:descents} for the respective last elements $\pm z,\pm (z+\epsilon),\ldots,\pm (z+h\epsilon)$ of $\sigma^{(j,0)},\sigma^{(j,1)},\ldots,\sigma^{(j,h)}$ implies that 
    \begin{equation}\label{eq:pi_order}
\pi(|z|)>\pi(|z+\epsilon|)>\pi(|z+2\epsilon|)>\dots > \pi(|z+h\epsilon|),
    \end{equation}
    and \cref{lem:descents_preserved} implies the corresponding order 
    \begin{equation}\label{eq:sigma_order}
\sigma(|z|)>\sigma(|z+\epsilon|)>\sigma(|z+2\epsilon|)>\dots > \sigma(|z+h\epsilon|).
    \end{equation}
    It suffices now to show that $\pi^{(j,i)}(|z+i\epsilon|)>\pi^{(j,i)}(|z+(i-1)\epsilon|)$. 

    We turn our attention to $\sigma^{(j,i-1)}$, where order property \ref{op:descents} implies that the last element $\pm (z+(i-1)\epsilon)\in \sigma_j^{(j,i-1)}$ was swapped with $\pm (z+i\epsilon)$, which appears as a non-last element in some cycle to its right. After swaps occur, $\pm (z+(i-1)\epsilon)$ is not the last element of a cycle in $\sigma^{(j,i)}$, and from this, we conclude \[\sigma^{(j,i)}(|z+(i-1)\epsilon|)=\pi^{(j,i)}(|z+(i-1)\epsilon|).\] 
    Swap property \ref{sp:large} for $\sigma^{(j,i-1)}$ implies that $\sigma^{(j,i-1)}(|z+i\epsilon|)<\sigma_{j+1,1}^{(j,i-1)}$, so after swaps are performed, $\sigma^{(j,i)}(|z+(i-1)\epsilon|)<\sigma_{j+1,1}^{(j,i)}$. Combined, we see that
    \[\pi^{(j,i)}(|z+i\epsilon|)=\sigma_{j+1,1}^{(j,i)}>\sigma^{(j,i)}(|z+(i-1)\epsilon|)=\pi^{(j,i)}(|z+(i-1)\epsilon|).\]
    Comparing with \eqref{eq:sigma_order}, we conclude $P_{\pi^{(j,i)},\sigma}(|z+i\epsilon|,|z+(i-1)\epsilon|)$ is \texttt{True}.

Since Algorithm \ref{algorithm} terminated iteration $j$ of the \texttt{for} loop at $\sigma^{(j,h)}$, we know that $P_{\pi,\sigma^{(j,h)}}(|z+h\epsilon|,|z+(h+1)\epsilon|)$ is \texttt{False}. \cref{lem:descents_preserved} implies $\operatorname{Des}(\pi)\cap [n-1]=\operatorname{Des}(\sigma)$, and combined with $P_{\pi^{(j,h)},\sigma}(|z+h\epsilon|,|z+(h+1)\epsilon|)$ being \texttt{True}, we conclude that $\min\{|z+h\epsilon|,|z+(h+1)\epsilon|\}\in \operatorname{Des}_{\Delta}(\pi^{(j,h)},\sigma^{(j,h)})$.  As $\pm (z+h\epsilon)$ is the last element of $\sigma_j^{(j,h)}$, \cref{lem:alg2_concatenation} implies that $\pm (z+(h+1)\epsilon)$ must appear as the non-last element in some cycle to the right of $\sigma_j^{(j,h)}$ and
    \[\pi^{(j,h)}(|z+h\epsilon|)>\pi^{(j,h)}(|z+(h+1)\epsilon|)=\sigma^{(j,h)}(|z+(h+1)\epsilon|)>\sigma^{(j,h)}(|z+h\epsilon|).\]
    Since $P_{\pi,\sigma^{(j,h)}}(|z+h\epsilon|,|z+(h+1)\epsilon|)$ is \texttt{False}, we conclude
    \begin{equation}\label{eq:phi_iteration2}
        \pi(|z+(h+1)\epsilon|)>\pi(|z+h\epsilon|).
    \end{equation}

    We now turn our attention to $\sigma^{(j,h-1)}$. As $\pm (z+(h+1)\epsilon)$ is not the last element in a cycle of $\sigma_j^{(j,h)}$, swap properties \ref{sp:right} and \ref{sp:last} for $\sigma^{(j,h-1)}$ imply that $\pm (z+(h+1)\epsilon)$ cannot be the last element in a cycle of $\sigma^{(j,h-1)}$. Additionally, order property \ref{op:descents} for $\sigma^{(j,h-1)}$ implies that $\pm (z+h\epsilon)$ was not the last element in a cycle of $\sigma^{(j,h-1)}$. Since $\pm (z+(h+1)\epsilon)$ and $\pm (z+h\epsilon)$ are non-last elements in the cycles of $\sigma^{(j,h-1)}$ containing them, order property \ref{op:descents} for $\sigma^{(j,h-1)}$ implies $\min\{|z+h\epsilon|,|z+(h+1)\epsilon|\}\notin \operatorname{Des}_{\Delta}(\pi,\sigma^{(j,h-1)})$, so combined with \eqref{eq:phi_iteration2}, we see that $\sigma^{(j,h-1)}(|z+(h+1)\epsilon|)>\sigma^{(j,h-1)}(|z+h\epsilon|)$. Then after performing swaps to obtain $\sigma^{(j,h)}$, we have that 
    \begin{equation}\label{eq:hpm1}
        \sigma^{(j,h)}(|z+(h+1)\epsilon|)>\sigma^{(j,h)}(|z+(h-1)\epsilon|).
    \end{equation}Additionally, these swaps result in $\pm (z+(h-1)\epsilon)$ being a non-last element of a cycle in $\sigma^{(j,h)}$. As both $\pm (z+(h-1)\epsilon)$ and $\pm (z+(h+1)\epsilon)$ are non-last elements in the cycles containing them, we conclude that \eqref{eq:hpm1} is equivalent to $\pi^{(j,h)}(|z+(h+1)\epsilon|)>\pi^{(j,h)}(|z+(h-1)\epsilon|).$

Fix $(\Omega_n)_{n\geq 1}$ to be either $(\operatorname{\mathfrak{C}}_{B,n})_{n\geq 1}$, $(\operatorname{\mathfrak{C}}_{D,n})_{n\geq 1}$, or $(\overline{\operatorname{\mathfrak{C}}_{D,n}})_{n\geq 1}$. Define $X_n:\Omega_n\to \mathbb{R}$ to be the random variable corresponding to the descent statistic on $\pi\in \Omega_n$ generated uniformly at random, and define $X_n':\Omega_n\to \mathbb{R}$ to be the corresponding descent statistic on $\Phi(\pi)$, where $\Phi$ is the function from \cref{thm:main_thm}. Using these, express
    \begin{equation}\label{eq:Xn_sum}
            \frac{X_{n}-\mu_{n}}{\sigma_{n}} =\frac{X_n-X'_n}{\sigma_{n}}+\frac{X'_n-\mu_{n-1}}{\sigma_{n-1}}\cdot \frac{\sigma_{n-1}}{\sigma_{n}}+\frac{\mu_{n-1}-\mu_{n}}{\sigma_{n}}.
    \end{equation}
    \cref{thm:main_thm} implies that $X_n-X'_n$ is a random variable that takes values in $\{0,1\}$. When $n$ is sufficiently large, \cref{thm:CLLSY} and \cref{thm:CM} imply $\mu_n=n/2$ and $\sigma_n=\sqrt{(n+1)/12}$. Combining these observations, it is straightforward to verify \eqref{eq:converge} to show that \[\frac{X_n-X'_n}{\sigma_{n}} \xrightarrow{p} 0, \quad  \frac{\sigma_{n-1}}{\sigma_{n}}=\frac{\sqrt{n}}{\sqrt{n+1}} \xrightarrow{p} 1, \quad  \text{ and }\quad  \frac{\mu_{n-1}-\mu_{n}}{\sigma_{n}} = \frac{-1/2}{\sqrt{(n+1)/12}} \xrightarrow{p} 0.\]
    \cref{thm:main_cor} implies that the distribution of $X'_n$ coincides with the distribution of the descent statistic for elements of $B_{n-1}$ generated uniformly at random. Hence, \cref{thm:CM} implies that 
    ${(X'_n-\mu_{n-1})}/{\sigma_{n-1}} \xrightarrow{d} \mathcal{N}(0,1)$. Returning to \eqref{eq:Xn_sum}, we now have that
    \begin{equation}\label{eq:Xn_sum2}
        \frac{X_{n}-\mu_{n}}{\sigma_{n}} =\underbrace{\frac{X_n-X'_n}{\sigma_{n}}}_{\xrightarrow{p}{0}}+\underbrace{\frac{X'_n-\mu_{n-1}}{\sigma_{n-1}}}_{\xrightarrow{d}{\mathcal{N}(0,1)}} \cdot \underbrace{\frac{\sigma_{n-1}}{\sigma_{n}}}_{\xrightarrow{p}{1}}+\underbrace{\frac{\mu_{n-1}-\mu_{n}}{\sigma_{n}}}_{\xrightarrow{p}{0}},
    \end{equation}
    so the result follows from \cref{thm:Slutsky}.

\label{thm:Snr}
    For any positive integers $n$ and $r$, there exists a function $\Phi: \operatorname{\mathfrak{C}}_{S,n+1,r}\to S_{n,r}$ with the following properties:
    \begin{enumerate}[label=(\alph*)]
        \item for all $(\omega,\tau)\in \operatorname{\mathfrak{C}}_{S,n+1,r}$, we have $\operatorname{Des}(\omega,\tau)\cap \{1,2,\ldots,n-1\}=\operatorname{Des}(\Phi(\omega,\tau))$, and
        \item the restriction of $\Phi$ to the elements of $\operatorname{\mathfrak{C}}_{S,n+1,r}$ with any fixed color is a bijection. 
    \end{enumerate}

Let $\phi:\operatorname{\mathfrak{C}}_{S,n+1}\to S_n$ be the bijection from \cref{thm:elizalde}. Extend this to a map $\Phi$ on $\operatorname{\mathfrak{C}}_{S,n+1,r}$ by defining $\Phi(\omega,\tau)=(\phi(\omega),\tau|_{[n]})$, where $\tau|_{[n]}$ denotes the restriction of $\tau$. For any $i\in [n-1]$, we consider a descent at position $i$ by focusing on the one-line notations for $(\omega,\tau)$ and $\Phi(\omega,\tau)$. 
    \begin{itemize}
        \item If $\tau(i)\neq \tau(i+1)$, then a descent at position $i$ in $(\omega,\tau)$ and $\Phi(\omega,\tau)$ is determined by the relative order of $\tau(i)=\tau|_{[n]}(i)$ and $\tau(i+1)=\tau|_{[n]}(i+1)$ as elements in $\mathbb{Z}$. Hence, $i\in \operatorname{Des}(\omega,\tau)$ if and only if $i\in \operatorname{Des}(\Phi(\omega,\tau))$. 
        \item If $\tau(i)=\tau(i+1)$, then a descent at position $i$ in $(\omega,\tau)$ and $\Phi(\omega,\tau)$ is determined by whether or not there is a descent at position $i$ in $\omega$ and $\phi(\omega)$. By \cref{thm:elizalde}, $i\in \operatorname{Des}(\omega)$ if and only if $i\in \operatorname{Des}(\phi(\omega))$, so we conclude $i\in \operatorname{Des}(\omega,\tau)$ if and only if $i\in \operatorname{Des}(\Phi(\omega,\tau))$.
    \end{itemize}
    Combined, we see that (a) holds. 

    For (b), we fix a color $c\in \mathbb{Z}$. We map each $(\omega',\tau')\in S_{n,r}$ to an element $(\omega,\tau)\in \operatorname{\mathfrak{C}}_{S,n+1,r}$ as follows:
    \begin{itemize}
        \item define $\omega=\phi^{-1}(\omega')$, and
        \item extend $\tau':[n]\to \mathbb{Z}_r$ to $\tau:[n+1]\to \mathbb{Z}_r$ by defining \[\tau(n+1)=c-\sum_{i\in [n]} \tau'(i)\in \mathbb{Z}_r.\]
    \end{itemize}
    It is straightforward to show that this is the inverse of $\Phi$ on the elements of $\operatorname{\mathfrak{C}}_{S,n+1,r}$ with color $c$.
